import json, re, random, chess, sys
R = json.load(open("re.json"))
def run(fen):
    for p, r in R: fen = re.sub(p, r, fen)
    return fen.split("\n")
fen = "<REDACTED_B64> w kq - 0 1"
exp = "<REDACTED_B64> b kq - 0 0\<REDACTED_B64> b kq - 0 0\<REDACTED_B64> b kq - 0 0"
print(sorted(run(fen)) == sorted(exp.split("\n")))
def check(fen):
    ours = [" ".join(x.split(" ")[:-2]) for x in run(fen)]
    b = chess.Board(fen); exp = set()
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN: continue
        c = b.copy(); c.push(m); exp.add(" ".join(c.fen().split(" ")[:-2]))
    ok = len(ours) == len(exp) and all(x in exp or x.rpartition(" ")[0]+" -" in exp for x in ours)
    if not ok:
        print("FAIL", fen); print(sorted(set(ours)-exp)); print(sorted(exp-set(ours))); sys.exit(1)
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
n = 0
for g in range(int(sys.argv[2]) if len(sys.argv) > 2 else 300):
    b = chess.Board()
    while not b.is_game_over() and b.ply() < 300:
        if b.turn == chess.WHITE:
            check(b.fen()); n += 1
        ms = list(b.legal_moves)
        # bias toward captures/pawn moves/castling for variety
        b.push(random.choice(ms))
print("ok", n)
EOF
